use std::error::Error;
use std::fs;
use std::path::Path;

use ab_glyph::{FontArc, PxScale};
use image::imageops::FilterType;
use image::{DynamicImage, GrayImage, ImageReader, Luma, Rgba, RgbaImage};
use imageproc::drawing::draw_text_mut;

const CHARACTER_RAMP: &[u8] = b"@#8&o:*. ";
const MAX_COLUMNS: u32 = 100;
const FONT_PATH: &str = "/System/Library/Fonts/Supplemental/Courier New.ttf";
const FONT_SIZE: f32 = 16.0;
const CHARACTER_WIDTH: u32 = 10;
const CHARACTER_HEIGHT: u32 = 18;

#[derive(Clone, Copy)]
enum AsciiMode {
    BlackAndWhite,
    Color,
}

fn luminance(red: u8, green: u8, blue: u8) -> u8 {
    (0.2126 * red as f32 + 0.7152 * green as f32 + 0.0722 * blue as f32) as u8
}

fn luminance_to_character(value: u8) -> char {
    let index = (value as usize * (CHARACTER_RAMP.len() - 1)) / u8::MAX as usize;
    CHARACTER_RAMP[index] as char
}

fn contrast_bounds(image: &GrayImage) -> (u8, u8) {
    let mut values: Vec<u8> = image.pixels().map(|pixel| pixel[0]).collect();
    values.sort_unstable();

    let last_index = values.len().saturating_sub(1);
    let black_point = values[last_index * 2 / 100];
    let white_point = values[last_index * 98 / 100].max(black_point.saturating_add(1));

    (black_point, white_point)
}

fn normalize_luminance(value: u8, black_point: u8, white_point: u8) -> u8 {
    if value <= black_point {
        return 0;
    }
    if value >= white_point {
        return u8::MAX;
    }

    ((value - black_point) as u16 * u8::MAX as u16
        / (white_point - black_point) as u16) as u8
}

fn resized_pixels(image: &DynamicImage) -> (RgbaImage, GrayImage, u32, u32) {
    let source = image.to_rgba8();
    let columns = source.width().min(MAX_COLUMNS).max(1);
    let rows = ((source.height() as f32 * columns as f32 / source.width() as f32) * 0.5)
        .round()
        .max(1.0) as u32;
    let resized = image::imageops::resize(&source, columns, rows, FilterType::Triangle);
    let grayscale = DynamicImage::ImageRgba8(resized.clone()).to_luma8();

    (resized, grayscale, columns, rows)
}

fn load_font() -> Result<FontArc, Box<dyn Error>> {
    FontArc::try_from_vec(fs::read(FONT_PATH)?)
        .map_err(|_| format!("could not load font at {FONT_PATH}").into())
}

fn draw_character(
    canvas: &mut RgbaImage,
    character: char,
    color: Rgba<u8>,
    x: u32,
    y: u32,
    font: &FontArc,
) {
    draw_text_mut(
        canvas,
        color,
        (x * CHARACTER_WIDTH) as i32,
        (y * CHARACTER_HEIGHT) as i32,
        PxScale::from(FONT_SIZE),
        font,
        &character.to_string(),
    );
}

fn render_ascii(image: &DynamicImage, mode: AsciiMode) -> Result<RgbaImage, Box<dyn Error>> {
    let (pixels, grayscale, columns, rows) = resized_pixels(image);
    let (black_point, white_point) = contrast_bounds(&grayscale);
    let mut output = RgbaImage::from_pixel(
        columns * CHARACTER_WIDTH,
        rows * CHARACTER_HEIGHT,
        Rgba([0, 0, 0, u8::MAX]),
    );
    let font = load_font()?;

    for y in 0..rows {
        for x in 0..columns {
            let source_pixel = pixels.get_pixel(x, y);
            let value = normalize_luminance(grayscale.get_pixel(x, y)[0], black_point, white_point);
            let character = luminance_to_character(value);
            let color = match mode {
                AsciiMode::BlackAndWhite => Rgba([u8::MAX, u8::MAX, u8::MAX, u8::MAX]),
                AsciiMode::Color => Rgba([
                    source_pixel[0],
                    source_pixel[1],
                    source_pixel[2],
                    u8::MAX,
                ]),
            };

            draw_character(&mut output, character, color, x, y, &font);
        }
    }

    Ok(output)
}

fn load_image(path: impl AsRef<Path>) -> image::ImageResult<DynamicImage> {
    ImageReader::open(path)?.decode()
}

fn convert_image_to_ascii(
    input_path: impl AsRef<Path>,
    output_path: impl AsRef<Path>,
    mode: AsciiMode,
) -> Result<(), Box<dyn Error>> {
    let image = load_image(input_path)?;
    let ascii_image = render_ascii(&image, mode)?;
    ascii_image.save(output_path)?;
    Ok(())
}

fn main() {
    let input_path = "input_image.png";

    convert_image_to_ascii(input_path, "output_image_bw.png", AsciiMode::BlackAndWhite)
        .and_then(|_| convert_image_to_ascii(input_path, "output_image_color.png", AsciiMode::Color))
        .unwrap_or_else(|error| eprintln!("Error converting image: {error}"));
}
